function showScreen(name) {
  Object.entries(screens).forEach(([key, screen]) => {
    const active = key === name;
    screen.hidden = !active;
    screen.classList.toggle("is-active", active);
  });
  window.scrollTo({ top: 0, behavior: "smooth" });
}

function beginQuiz() {
  state.current = 0;
  showScreen("quiz");
  renderQuestion();
}

function openMagicGate() {
  if (state.gateBusy) return;
  const reduceMotion = window.matchMedia("(prefers-reduced-motion: reduce)").matches;
  if (reduceMotion) {
    beginQuiz();
    return;
  }

  state.gateBusy = true;
  el.start.disabled = true;
  el.gate.hidden = false;
  el.gate.classList.remove("is-opening", "is-crossing");
  document.body.classList.add("is-gate-opening");

  setTimeout(() => el.gate.classList.add("is-opening"), 24);

  setTimeout(() => {
    beginQuiz();
    el.gate.classList.add("is-crossing");
  }, 1550);

  setTimeout(() => {
    el.gate.hidden = true;
    el.gate.classList.remove("is-opening", "is-crossing");
    document.body.classList.remove("is-gate-opening");
    el.start.disabled = false;
    state.gateBusy = false;
  }, 2200);
}

function storyPanel(scene, index) {
  const asset = storyAssets[scene];
  if (!asset) return optionArt(scene, index);

  const columns = scene === "teamwork" ? 3 : 2;
  const rows = 2;
  const column = index % columns;
  const row = Math.floor(index / columns);

  return `<span class="choice-scene-crop" style="--story-image:url('${asset}')">
    <span class="choice-scene-window">
      <img class="choice-scene-image" src="${asset}" alt="" draggable="false" style="--panel-columns:${columns};--panel-rows:${rows};--panel-column:${column};--panel-row:${row}" />
    </span>
    <span class="choice-scene-glint"></span>
  </span>`;
}

function storyMontage(scene) {
  const asset = storyAssets[scene];
  if (!asset) return sceneSVG(scene);
  return `<span class="scene-story-poster" style="--story-image:url('${asset}')" aria-hidden="true"></span>
    <span class="scene-choice-focus" aria-hidden="true">
      <span class="scene-focus-aura"></span>
      <span class="scene-focus-rings"><i></i><i></i></span>
      <span class="scene-choice-caption"></span>
    </span>`;
}

function introStory(scene) {
  const asset = storyAssets[scene];
  if (!asset) return sceneSVG(scene);
  return `<span class="intro-story-poster" style="--story-image:url('${asset}')" aria-hidden="true">
    <img src="${asset}" alt="" draggable="false" />
  </span>`;
}

function projectStoryPoint(scene, point) {
  const rect = el.sceneArt.getBoundingClientRect();
  if (!rect.width || !rect.height) return point;
  const imageAspect = scene === "teamwork" ? 1.5 : 1;
  const containerAspect = rect.width / rect.height;
  let width = rect.width;
  let height = rect.height;
  let offsetX = 0;
  let offsetY = 0;
  if (imageAspect > containerAspect) {
    height = width / imageAspect;
    offsetY = (rect.height - height) / 2;
  } else {
    width = height * imageAspect;
    offsetX = (rect.width - width) / 2;
  }
  return {
    ...point,
    x: ((offsetX + width * point.x / 100) / rect.width) * 100,
    y: ((offsetY + height * point.y / 100) / rect.height) * 100
  };
}

function getSceneFocusPoint(scene, index) {
  if (scene === "forest") {
    const point = [
      { x: 23, y: 29, hue: 43 },
      { x: 76, y: 30, hue: 188 },
      { x: 17, y: 74, hue: 272 },
      { x: 76, y: 74, hue: 316 }
    ][index];
    return projectStoryPoint(scene, point);
  }
  const columns = scene === "teamwork" ? 3 : 2;
  const column = index % columns;
  const row = Math.floor(index / columns);
  return projectStoryPoint(scene, {
    x: ((column + .5) / columns) * 100,
    y: ((row + .5) / 2) * 100,
    hue: [43, 188, 272, 316, 128][index] || 43
  });
}

function updateSceneResponse(question, index) {
  const focus = el.sceneArt.querySelector(".scene-choice-focus");
  if (!focus) return;
  const selected = Number.isInteger(index) && index >= 0;
  el.sceneArt.classList.toggle("has-choice-response", selected);
  if (!selected) {
    delete el.sceneArt.dataset.choice;
    return;
  }

  const point = getSceneFocusPoint(question.scene, index);
  if (!point) return;
  el.sceneArt.style.setProperty("--focus-x", `${point.x}%`);
  el.sceneArt.style.setProperty("--focus-y", `${point.y}%`);
  el.sceneArt.style.setProperty("--focus-hue", String(point.hue));
  const caption = focus.querySelector(".scene-choice-caption");
  const letter = ["A", "B", "C", "D", "E"][index];
  el.sceneArt.dataset.choice = letter.toLowerCase();
  caption.textContent = `${letter} · ${sceneFocusCopy[question.scene]?.[index] || "这份选择亮起来了"}`;
  focus.classList.remove("is-flashing");
  requestAnimationFrame(() => focus.classList.add("is-flashing"));
}

function preloadUpcomingStory() {
  const nextQuestion = questions[state.current + 1];
  const asset = nextQuestion && storyAssets[nextQuestion.scene];
  if (!asset) return;
  const image = new Image();
  image.src = asset;
}

function renderQuestion() {
  const q = questions[state.current];
  const number = state.current + 1;
  stopSpeech();
  el.progressLabel.textContent = number <= 2 ? `第 ${number} 次试炼 · 入学资料` : `第 ${number} 次试炼 · 心灵冒险`;
  el.progressCount.textContent = `${number} / ${questions.length}`;
  el.progressTrack.setAttribute("aria-valuenow", String(number));
  el.progressFill.style.width = `${(number / questions.length) * 100}%`;
  el.sceneKicker.textContent = q.sceneTitle;
  el.sceneTip.textContent = q.sceneTip;
  el.sceneArt.dataset.scene = q.scene;
  el.sceneArt.classList.toggle("is-choice-scene", Boolean(q.options));
  const hasIntroStory = !q.options && Boolean(storyAssets[q.scene]);
  el.sceneArt.classList.toggle("is-intro-scene", hasIntroStory);
  el.sceneArt.innerHTML = q.options ? storyMontage(q.scene) : hasIntroStory ? introStory(q.scene) : sceneSVG(q.scene);
  el.questionNumber.textContent = `QUESTION ${String(number).padStart(2, "0")}`;
  el.questionTitle.textContent = q.title;
  el.questionDescription.textContent = q.description || "";
  el.fieldError.textContent = "";
  el.prev.style.visibility = state.current === 0 ? "hidden" : "visible";
  el.next.querySelector("span").textContent = number === questions.length ? "封印并提交" : "下一题";
  renderAnswer(q);
  updateSceneResponse(q, Number.isInteger(state.answers[q.id]) ? state.answers[q.id] : -1);
  preloadUpcomingStory();
  updateAnswerState();
  el.quizLayout.style.animation = "none";
  requestAnimationFrame(() => {
    el.quizLayout.style.animation = "questionIn .45s var(--ease) both";
  });
  setTimeout(() => {
    const focusTarget = el.answerArea.querySelector("input");
    if (focusTarget && q.type !== "text" && q.type !== "number") focusTarget.focus({ preventScroll: true });
  }, 150);
}

function renderAnswer(q) {
  const saved = state.answers[q.id] ?? "";
  if (q.type === "text" || q.type === "number") {
    el.answerArea.innerHTML = `
      <div class="text-answer">
        <label for="answerInput">${escapeHTML(q.label)}</label>
        <input id="answerInput" name="${q.id}" type="${q.type}" ${q.type === "number" ? 'inputmode="numeric" min="1" max="99"' : 'maxlength="12"'} value="${escapeHTML(String(saved))}" placeholder="${escapeHTML(q.placeholder)}" autocomplete="${q.type === "text" ? "name" : "off"}" aria-describedby="answerHint fieldError" />
        <small class="input-hint" id="answerHint">${escapeHTML(q.hint)}</small>
      </div>`;
    const input = document.getElementById("answerInput");
    input.addEventListener("input", () => {
      state.answers[q.id] = input.value.trim();
      el.fieldError.textContent = "";
      updateAnswerState();
    });
    setTimeout(() => input.focus({ preventScroll: true }), 180);
    return;
  }

  const letters = ["A", "B", "C", "D", "E"];
  el.answerArea.innerHTML = `
    <fieldset class="choice-list${q.options.length % 2 ? " has-odd" : ""}${q.options.length === 5 ? " has-five" : ""}">
      <legend class="sr-only">请选择一个答案</legend>
      ${q.options.map((option, index) => {
        const selected = saved === index;
        return `
          <label class="choice-card${selected ? " is-selected" : ""}" data-index="${index}">
            <input class="choice-input" type="radio" name="${q.id}" value="${index}" ${selected ? "checked" : ""} />
            <span class="choice-visual" aria-hidden="true">${storyPanel(q.scene, index)}</span>
            <span class="choice-copy">
              <span class="choice-letter">${letters[index]}</span>
              <span class="choice-text">${escapeHTML(option)}</span>
              <span class="choice-check" aria-hidden="true"></span>
            </span>
          </label>`;
      }).join("")}
    </fieldset>`;

  el.answerArea.querySelectorAll(".choice-input").forEach(input => {
    input.addEventListener("change", event => {
      const selectedIndex = Number(event.target.value);
      state.answers[q.id] = selectedIndex;
      el.answerArea.querySelectorAll(".choice-card").forEach(card => card.classList.remove("is-selected"));
      const selectedCard = event.target.closest(".choice-card");
      selectedCard.classList.add("is-selected", "is-just-selected");
      setTimeout(() => selectedCard.classList.remove("is-just-selected"), 700);
      el.fieldError.textContent = "";
      updateAnswerState();
      updateSceneResponse(q, selectedIndex);
      createSparkleBurst();
    });
  });
}

function updateAnswerState() {
  const q = questions[state.current];
  const value = state.answers[q.id];
  const complete = value !== undefined && value !== null && String(value).trim() !== "";
  el.next.disabled = !complete;
  el.answerState.textContent = complete ? "已记录魔法答案" : "等待你的答案";
  el.answerState.classList.toggle("is-done", complete);
}

function validateCurrent() {
  const q = questions[state.current];
  const value = state.answers[q.id];
  if (value === undefined || value === null || String(value).trim() === "") {
    el.fieldError.textContent = q.type ? "请先填写这一项，再继续冒险。" : "请先选择一个答案，再继续冒险。";
    return false;
  }
  if (q.id === "age") {
    const age = Number(value);
    if (!Number.isInteger(age) || age < 1 || age > 99) {
      el.fieldError.textContent = "请填写正确的年龄数字。";
      return false;
    }
  }
  return true;
}

function nextQuestion() {
  if (!validateCurrent()) return;
  if (state.current < questions.length - 1) {
    state.current += 1;
    renderQuestion();
    window.scrollTo({ top: 0, behavior: "smooth" });
    return;
  }
  submitQuiz();
}

function previousQuestion() {
  if (state.current > 0) {
    state.current -= 1;
    renderQuestion();
    window.scrollTo({ top: 0, behavior: "smooth" });
  }
}

function submitQuiz() {
  stopSpeech();
  try {
    localStorage.setItem("youfangMagicDemo", JSON.stringify({
      answers: state.answers,
      submittedAt: new Date().toISOString(),
      version: "demo-1.0"
    }));
  } catch (_) {}
  showScreen("processing");
  setTimeout(showAdmission, 2500);
}

function showAdmission() {
  const name = state.answers.name || "小魔法师";
  el.successName.textContent = name;
  el.certificateName.textContent = name;
  el.certificateDate.textContent = "2026 年 8 月";
  showScreen("admission");
}

function restart() {
  stopSpeech();
  state.current = 0;
  state.answers = {};
  state.gateBusy = false;
  el.gate.hidden = true;
  el.gate.classList.remove("is-opening", "is-crossing");
  document.body.classList.remove("is-gate-opening");
  el.start.disabled = false;
  try { localStorage.removeItem("youfangMagicDemo"); } catch (_) {}
  showScreen("home");
}

function speakQuestion() {
  if (!("speechSynthesis" in window)) {
    showToast("当前浏览器暂不支持语音朗读");
    return;
  }
  if (window.speechSynthesis.speaking) {
    stopSpeech();
    showToast("已停止朗读");
    return;
  }
  const q = questions[state.current];
  const text = [q.title, q.description, ...(q.options || [])].filter(Boolean).join("。 ");
  const utterance = new SpeechSynthesisUtterance(text);
  utterance.lang = "zh-CN";
  utterance.rate = 0.82;
  utterance.pitch = 1.08;
  state.speech = utterance;
  window.speechSynthesis.speak(utterance);
  showToast("正在朗读题目，再次点击可停止");
}

function stopSpeech() {
  if ("speechSynthesis" in window) window.speechSynthesis.cancel();
  state.speech = null;
}

function createSparkleBurst() {
  const colors = ["#f6bd4a", "#7b64d1", "#70c9a0", "#ef8e4a"];
  for (let i = 0; i < 10; i += 1) {
    const star = document.createElement("i");
    star.className = "burst-star";
    star.style.left = `${55 + Math.random() * 25}%`;
    star.style.top = `${45 + Math.random() * 20}%`;
    star.style.background = colors[i % colors.length];
    star.style.setProperty("--x", `${(Math.random() - .5) * 150}px`);
    star.style.setProperty("--y", `${(Math.random() - .5) * 130}px`);
    el.sparkles.appendChild(star);
    setTimeout(() => star.remove(), 800);
  }
}

function showToast(message) {
  el.toast.textContent = message;
  el.toast.classList.add("is-visible");
  clearTimeout(showToast.timer);
  showToast.timer = setTimeout(() => el.toast.classList.remove("is-visible"), 2400);
}

