  ctx.font = '600 20px Georgia, serif';
  ctx.fillText("YOUFANG MAGIC SCHOOL", 700, 357);
  ctx.fillStyle = "#30204f";
  ctx.font = '900 92px "STKaiti", "KaiTi", serif';
  ctx.fillText("录 取 通 知 书", 700, 485);
  ctx.fillStyle = "#87652e";
  ctx.font = '600 23px Georgia, serif';
  ctx.fillText("LETTER OF ACCEPTANCE", 700, 528);

  ctx.strokeStyle = "#bd8731";
  ctx.lineWidth = 3;
  ctx.beginPath(); ctx.moveTo(315, 580); ctx.lineTo(660, 580); ctx.stroke();
  drawDiamond(ctx, 700, 580, 12, "#e7a53b");
  ctx.beginPath(); ctx.moveTo(740, 580); ctx.lineTo(1085, 580); ctx.stroke();

  ctx.fillStyle = "#432c76";
  const nameSize = Math.max(42, Math.min(54, 58 - Math.max(0, name.length - 4) * 3));
  ctx.font = `700 ${nameSize}px "STKaiti", "KaiTi", serif`;
  ctx.fillText(`亲爱的 ${name} 同学：`, 700, 675);
  ctx.strokeStyle = "rgba(184,130,43,.55)";
  ctx.lineWidth = 3;
  ctx.beginPath(); ctx.moveTo(430, 698); ctx.lineTo(970, 698); ctx.stroke();

  const letterLines = [
    { text: "我们愉快地通知你：", color: "#5a486b", weight: 500 },
    { text: "你已被有方心理魔法学校录取，", color: "#3d285f", weight: 700 },
    { text: "正式成为本校的新一届小魔法师。", color: "#3d285f", weight: 700 },
    { text: "请于 8 月 3 日，", color: "#5a486b", weight: 600 },
    { text: "带上你的好奇心、勇气和一点点魔法，", color: "#5a486b", weight: 500 },
    { text: "准时来校报到。", color: "#5a486b", weight: 500 },
    { text: "在这里，你将学会关于生命、", color: "#5a486b", weight: 500 },
    { text: "情感、财商、商品设计的魔法。", color: "#5a486b", weight: 500 },
    { text: "期待你的到来！", color: "#7a5120", weight: 700 }
  ];
  letterLines.forEach((line, index) => {
    ctx.fillStyle = line.color;
    ctx.font = `${line.weight} 36px "STKaiti", "KaiTi", serif`;
    ctx.fillText(line.text, 700, 775 + index * 66);
  });

  ctx.textAlign = "right";
  ctx.fillStyle = "rgba(255,249,231,.82)";
  ctx.beginPath();
  ctx.roundRect(800, 1565, 390, 158, 18);
  ctx.fill();
  ctx.fillStyle = "#44345f";
