function drawCorner(ctx, x, y, sx, sy) {
  ctx.save();
  ctx.translate(x, y);
  ctx.scale(sx, sy);
  ctx.strokeStyle = "#6b50ad";
  ctx.lineWidth = 5;
  ctx.beginPath();
  ctx.moveTo(0, 80); ctx.quadraticCurveTo(0, 0, 80, 0);
  ctx.moveTo(18, 76); ctx.quadraticCurveTo(18, 18, 76, 18);
  ctx.stroke();
  drawDiamond(ctx, 18, 18, 9, "#dca743");
  ctx.restore();
}

function drawStar(ctx, cx, cy, outer, inner, color) {
  ctx.save();
  ctx.beginPath();
  for (let i = 0; i < 10; i += 1) {
    const radius = i % 2 === 0 ? outer : inner;
    const angle = -Math.PI / 2 + i * Math.PI / 5;
    const x = cx + Math.cos(angle) * radius;
    const y = cy + Math.sin(angle) * radius;
    i === 0 ? ctx.moveTo(x, y) : ctx.lineTo(x, y);
  }
  ctx.closePath();
  ctx.fillStyle = color;
  ctx.fill();
  ctx.restore();
}

function drawDiamond(ctx, cx, cy, size, color) {
  ctx.save();
  ctx.translate(cx, cy);
  ctx.rotate(Math.PI / 4);
  ctx.fillStyle = color;
  ctx.fillRect(-size / 2, -size / 2, size, size);
  ctx.restore();
}

function drawWrappedCenteredText(ctx, text, x, y, maxWidth, lineHeight) {
  const chars = [...text];
  let line = "";
  const lines = [];
  chars.forEach(char => {
    const test = line + char;
    if (ctx.measureText(test).width > maxWidth && line) {
      lines.push(line);
      line = char;
    } else {
      line = test;
    }
  });
  if (line) lines.push(line);
  lines.forEach((item, index) => ctx.fillText(item, x, y + index * lineHeight));
}

function drawSeal(ctx, cx, cy) {
  ctx.save();
  ctx.translate(cx, cy);
  ctx.rotate(-.12);
  ctx.fillStyle = "#9f3144";
  ctx.beginPath(); ctx.arc(0, 0, 102, 0, Math.PI * 2); ctx.fill();
  ctx.strokeStyle = "#e5a17f";
  ctx.lineWidth = 8;
  ctx.beginPath(); ctx.arc(0, 0, 84, 0, Math.PI * 2); ctx.stroke();
  ctx.fillStyle = "#ffe3aa";
  ctx.textAlign = "center";
  ctx.font = '900 39px "STKaiti", "KaiTi", serif';
  ctx.fillText("有方", 0, 2);
  ctx.font = '700 20px "Microsoft YaHei", sans-serif';
  ctx.fillText("魔法学校", 0, 36);
  ctx.restore();
}

function escapeHTML(value) {
  return String(value).replace(/[&<>'"]/g, char => ({ "&": "&amp;", "<": "&lt;", ">": "&gt;", "'": "&#39;", '"': "&quot;" }[char]));
}

