el.start.addEventListener("click", openMagicGate);
el.home.addEventListener("click", restart);
el.prev.addEventListener("click", previousQuestion);
el.next.addEventListener("click", nextQuestion);
el.speak.addEventListener("click", speakQuestion);
el.download.addEventListener("click", downloadCertificate);
el.restart.addEventListener("click", restart);
el.restartIcon.addEventListener("click", restart);

document.querySelectorAll(".brand").forEach(brand => {
  brand.addEventListener("click", event => {
    event.preventDefault();
    restart();
  });
});

document.addEventListener("keydown", event => {
  if (event.key === "Enter" && !screens.quiz.hidden && event.target.tagName !== "BUTTON" && !el.next.disabled) {
    event.preventDefault();
    nextQuestion();
  }
});

let sceneResizeFrame = 0;
window.addEventListener("resize", () => {
  cancelAnimationFrame(sceneResizeFrame);
  sceneResizeFrame = requestAnimationFrame(() => {
    const question = questions[state.current];
    const answer = question && state.answers[question.id];
    if (!screens.quiz.hidden && question?.options && Number.isInteger(answer)) {
      updateSceneResponse(question, answer);
    }
  });
});
